 WHERE NOT (x.value->>0=c.v#>>'{remove,kind}' AND x.value->>1=c.v#>>'{remove,object}'
 AND x.value->>4 IN (SELECT jsonb_array_elements_text(c.v#>'{remove,grantees}'))
